def _load_dict_artifact(artifact: dict) -> np.ndarray | None:
    """Decode embedded signal matrices persisted by the miners.

    Supported formats:
      * ``data_b64`` + ``n_dates``/``n_symbols``:
        gzip-compressed float32 little-endian rows, base64 encoded.
      * ``data`` + ``shape``/``columns`` with format ``base64:zlib:csv``:
        base64(zlib(csv with header row date,<symbols>)).
    """
    import base64
    import gzip
    import io
    import zlib

    try:
        data_b64 = artifact.get("data_b64")
        if data_b64:
            raw = base64.b64decode(data_b64)
            try:
                payload_bytes = gzip.decompress(raw)
            except (OSError, EOFError):
                payload_bytes = zlib.decompress(raw)
            n_dates = int(artifact["n_dates"])
            n_symbols = int(artifact["n_symbols"])
            matrix = np.frombuffer(payload_bytes, dtype="<f4").reshape(n_dates, n_symbols)
            return matrix if matrix.ndim >= 2 else None
        data = artifact.get("data")
        if data:
            try:
                payload_bytes = zlib.decompress(base64.b64decode(data))
            except (OSError, zlib.error, TypeError):
                payload_bytes = base64.b64decode(data)
            text = payload_bytes.decode("utf-8", errors="replace")
            rows = []
            for line in text.splitlines():
                if not line.strip() or line.startswith("date,"):
                    continue
                rows.append([float(v) if v not in ("", "NA") else np.nan
                             for v in line.split(",")[1:]])
            if not rows:
                return None
            matrix = np.asarray(rows, dtype=float)
            return matrix if matrix.ndim >= 2 else None
    except (KeyError, TypeError, ValueError, OSError, EOFError, zlib.error):
        return None
    return None
