def sign_streak(ret):
    cols = {}
    for s in ret.columns:
        r = ret[s].values
        out = np.full(len(r), np.nan)
        prev = 0.0
        for i in range(len(r)):
            if not np.isfinite(r[i]):
                prev = 0.0
                continue
            sg = 1.0 if r[i] > 0 else (-1.0 if r[i] < 0 else 0.0)
            if sg == 0:
                prev = 0.0
                out[i] = 0.0
            elif np.sign(prev) == sg or prev == 0.0:
